//! The object model: one `#[pyclass]` per IR type, with the IR's field names, order and defaults
//! (`decisions/0012`). Conversion to and from the IR is generated by [`model!`](crate::model).

use oxymorph_schema as ir;
use pyo3::prelude::*;
use pyo3::types::{PyBytes, PyTuple, PyType};

use crate::builders;
use crate::convert::{value_error, LiveDict, LiveList, Model, Path};
use crate::enums::Enum;
use crate::model;

model! {
    PrefixedValue => ir::PrefixedValue {
        double_value: f64,
        prefix: Enum<ir::Siprefix>,
    }
}

model! {
    ModelReference => ir::ModelReference {
        model_interface_name: String,
        arguments: LiveDict<ParameterValue>,
    }
}

