model! {
    Module => ir::Module {
        name: String,
        class_name: String,
        ports: LiveList<Port>,
        parameters: LiveList<Parameter>,
        model_interfaces: LiveList<ModelInterface>,
        module_references: LiveList<ModuleReference>,
        connections: LiveList<Connection>,
        buses: LiveList<Bus>,
        properties: LiveDict<String>,
        directives: LiveList<Directive>,
        macros: LiveList<Macro>,
    }
    methods {
        #[pyo3(signature = (*module_references))]
        fn add<'py>(
            slf: PyRef<'py, Self>,
            module_references: &Bound<'py, PyTuple>,
        ) -> PyResult<PyRef<'py, Self>> {
            let list = slf.module_references.bind(slf.py());
            for module_reference in module_references.iter() {
                list.append(module_reference.cast::<ModuleReference>()?)?;
            }
            Ok(slf)
        }

        /// A port of this module, appended.
        #[pyo3(signature = (name, *, direction = None, domain = None, width = 0, discipline = String::new(), properties = None))]
        fn add_terminal<'py>(
            slf: PyRef<'py, Self>,
            name: String,
            direction: Option<Enum<ir::PortDirection>>,
            domain: Option<Enum<ir::SignalDomain>>,
            width: u32,
            discipline: String,
            properties: Option<LiveDict<String>>,
        ) -> PyResult<PyRef<'py, Self>> {
            let py = slf.py();
            let port = builders::port(py, name, direction, domain, width, discipline, properties);
            slf.ports.bind(py).append(Py::new(py, port)?)?;
            Ok(slf)
        }

        /// Chained connections on net `net_name`: endpoints A, B, C give A→B and B→C. An endpoint
        /// is `(instance_name, port_name)`; instance "" is this module's own port. Fewer than two
        /// endpoints raise `ValueError`, as in kfnetlist: pass a lone terminal twice to name its net.
        #[pyo3(signature = (net_name, *endpoints, domain = None, properties = None))]
        fn connect<'py>(
            slf: PyRef<'py, Self>,
            net_name: String,
            endpoints: Vec<(String, String)>,
            domain: Option<Enum<ir::SignalDomain>>,
            properties: Option<LiveDict<String>>,
        ) -> PyResult<PyRef<'py, Self>> {
            let py = slf.py();
            if endpoints.len() < 2 {
                return Err(value_error(format!(
                    "connect('{net_name}'): need ≥ 2 endpoints, got {}",
                    endpoints.len()
                )));
            }
            let connections = slf.connections.bind(py);
            for pair in endpoints.windows(2) {
                let source = pair[0].clone();
                let target = pair[1].clone();
                let connection_properties = match &properties {
                    Some(shared) => Some(shared.bind(py).extract()?),
                    None => None,
                };
                let connection = builders::connection(
                    py,
                    net_name.clone(),
                    source,
                    target,
                    domain,
                    connection_properties,
                )?;
                connections.append(Py::new(py, connection)?)?;
            }
            Ok(slf)
        }
    }
}

