model! {
    /// The top-level container. `add` sets `top_module` to the first module added when unset.
    Circuit => ir::Circuit {
        name: String,
        top_module: String,
        modules: LiveList<Module>,
        ext_modules: LiveList<ExternalModule>,
        properties: LiveDict<String>,
        directives: LiveList<Directive>,
        simulation: Option<Py<Simulation>>,
        libraries: LiveDict<ExternalLibrary>,
        macros: LiveList<Macro>,
    }
    methods {
        #[pyo3(signature = (*modules))]
        fn add<'py>(
            mut slf: PyRefMut<'py, Self>,
            modules: &Bound<'py, PyTuple>,
        ) -> PyResult<PyRefMut<'py, Self>> {
            let py = slf.py();
            for module in modules.iter() {
                let module = module.cast::<Module>()?;
                if slf.top_module.is_empty() {
                    slf.top_module = module.try_borrow()?.name.clone();
                }
                slf.modules.bind(py).append(module)?;
            }
            Ok(slf)
        }

        #[pyo3(signature = (*ext_modules))]
        fn add_ext<'py>(
            slf: PyRef<'py, Self>,
            ext_modules: &Bound<'py, PyTuple>,
        ) -> PyResult<PyRef<'py, Self>> {
            let list = slf.ext_modules.bind(slf.py());
            for ext_module in ext_modules.iter() {
                list.append(ext_module.cast::<ExternalModule>()?)?;
            }
            Ok(slf)
        }

        fn add_library<'py>(
            slf: PyRef<'py, Self>,
            name: String,
            library: Bound<'py, ExternalLibrary>,
        ) -> PyResult<PyRef<'py, Self>> {
            slf.libraries.bind(slf.py()).set_item(name, library)?;
            Ok(slf)
        }

        fn to_json_pretty(&self, py: Python<'_>) -> PyResult<String> {
            self.to_ir(py, &Path::ROOT)?.to_json_pretty().map_err(value_error)
        }

        fn to_yaml(&self, py: Python<'_>) -> PyResult<String> {
            self.to_ir(py, &Path::ROOT)?.to_yaml().map_err(value_error)
        }

        #[classmethod]
        fn from_yaml(_class: &Bound<'_, PyType>, py: Python<'_>, text: &str) -> PyResult<Self> {
            Self::from_ir(py, &ir::Circuit::from_yaml(text).map_err(value_error)?)
        }

        fn to_proto_bytes<'py>(&self, py: Python<'py>) -> PyResult<Bound<'py, PyBytes>> {
            Ok(PyBytes::new(py, &self.to_ir(py, &Path::ROOT)?.to_proto_bytes()))
        }

        #[classmethod]
        fn from_proto_bytes(_class: &Bound<'_, PyType>, py: Python<'_>, data: &[u8]) -> PyResult<Self> {
            Self::from_ir(py, &ir::Circuit::from_proto_bytes(data).map_err(value_error)?)
        }
    }
}

model! {
    UnaryOp => ir::UnaryOp {
        op: Enum<ir::Operator>,
        operand: Option<Py<Expression>> as boxed,
    }
}

model! {
    BinaryOp => ir::BinaryOp {
        op: Enum<ir::Operator>,
        lhs: Option<Py<Expression>> as boxed,
        rhs: Option<Py<Expression>> as boxed,
    }
}

model! {
    Call => ir::Call {
        name: String,
        args: LiveList<Expression>,
    }
}

model! {
    Ternary => ir::Ternary {
        cond: Option<Py<Expression>> as boxed,
        then: Option<Py<Expression>> as boxed,
        otherwise: Option<Py<Expression>> as boxed,
    }
}

model! {
    /// One node kind set at most (a oneof).
    Expression => ir::Expression check ir::Expression::check_oneof {
        literal: Option<Py<PrefixedValue>>,
        reference: Option<String>,
        unary: Option<Py<UnaryOp>>,
        binary: Option<Py<BinaryOp>>,
        call: Option<Py<Call>>,
        ternary: Option<Py<Ternary>>,
        raw: Option<String>,
    }
}

pub fn add_classes(module: &Bound<'_, PyModule>) -> PyResult<()> {
    module.add_class::<PrefixedValue>()?;
    module.add_class::<ModelReference>()?;
    module.add_class::<ParameterValue>()?;
    module.add_class::<Parameter>()?;
    module.add_class::<Directive>()?;
    module.add_class::<Macro>()?;
    module.add_class::<ModelInterface>()?;
    module.add_class::<PortReference>()?;
    module.add_class::<Port>()?;
    module.add_class::<Connection>()?;
    module.add_class::<Bus>()?;
    module.add_class::<ModuleReference>()?;
    module.add_class::<Module>()?;
    module.add_class::<ExternalModule>()?;
    module.add_class::<ExternalLibrary>()?;
    module.add_class::<Analysis>()?;
    module.add_class::<OutputRequest>()?;
    module.add_class::<Measurement>()?;
    module.add_class::<InitialCondition>()?;
    module.add_class::<Waveform>()?;
    module.add_class::<Stimulus>()?;
    module.add_class::<Simulation>()?;
    module.add_class::<Circuit>()?;
    module.add_class::<UnaryOp>()?;
    module.add_class::<BinaryOp>()?;
    module.add_class::<Call>()?;
    module.add_class::<Ternary>()?;
    module.add_class::<Expression>()?;
    Ok(())
}
